const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});
const rawCompany = String(payload.companyName || payload.company || payload.name || '').trim();
const rawEmail = String(payload.email || '').trim().toLowerCase();
const rawUrl = String(payload.website || payload.url || payload.domain || '').trim();
const rawPhone = String(payload.phone || '').trim();

const protoPrefix = new RegExp('^https?:' + '/' + '/', 'i');
let cleanDomain = rawUrl.replace(protoPrefix, '').split('/')[0].split('?')[0].toLowerCase();
if (cleanDomain.startsWith('www.')) {
  cleanDomain = cleanDomain.substring(4);
}

if (!cleanDomain && rawEmail.includes('@')) {
  cleanDomain = rawEmail.split('@')[1];
}

const domainRegex = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$/;
const isValidDomain = domainRegex.test(cleanDomain);

const freeEmailDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com', 'aol.com', 'zoho.com', 'protonmail.com'];
const isBusinessEmail = rawEmail.includes('@') && !freeEmailDomains.includes(rawEmail.split('@')[1]);

const cleanPhone = rawPhone.replace(/[^0-9+]/g, '');

const crypto = require('crypto');
const dedupSource = (cleanDomain || rawCompany.toLowerCase() + '|' + String(payload.city || '').toLowerCase()).trim();
const dedupKey = crypto.createHash('sha256').update(dedupSource).digest('hex');

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    lead: {
      companyName: rawCompany,
      domain: cleanDomain,
      isValidDomain,
      email: rawEmail,
      isBusinessEmail,
      phone: cleanPhone,
      city: String(payload.city || '').trim(),
      countryCode: String(payload.countryCode || payload.country || 'IN').trim().toUpperCase(),
      industry: String(payload.industry || payload.category || 'General').trim(),
      source: String(payload.source || 'apify_directory').trim(),
      sourceUrl: String(payload.sourceUrl || '').trim(),
      linkedinUrl: String(payload.linkedinUrl || payload.socialUrl || '').trim(),
      dedupKey,
      discoveredAt: new Date().toISOString()
    }
  }
}];

const item = $input.first().json;
const lead = item.lead || {};
const suppressedDomains = ['mailinator.com', 'tempmail.com', 'guerrillamail.com', 'throwawaymail.com', '10minutemail.com', 'spam.com'];
const domain = lead.domain || '';
const email = lead.email || '';
const emailDomain = email.includes('@') ? email.split('@')[1] : '';

let isSuppressed = false;
let suppressionReason = null;

if (suppressedDomains.includes(domain) || suppressedDomains.includes(emailDomain)) {
  isSuppressed = true;
  suppressionReason = 'Disposable or test email domain';
}

const blockedJurisdictions = ['RU', 'KP', 'IR', 'SY'];
if (blockedJurisdictions.includes(lead.countryCode)) {
  isSuppressed = true;
  suppressionReason = 'Jurisdiction under mandatory compliance embargo';
}

const strictOptInJurisdictions = ['DE', 'AT'];
const requiresOptIn = strictOptInJurisdictions.includes(lead.countryCode);

return [{
  json: {
    eventId: item.eventId,
    lead: {
      ...lead,
      isSuppressed,
      suppressionReason,
      requiresOptIn,
      dedupStatus: 'unique'
    }
  }
}];

const item = $input.first().json;
const lead = item.lead || {};

const linkedin = lead.linkedinUrl || '';
const hasLinkedIn = /linkedin\.com\/(company|in)\/[a-zA-Z0-9_-]+/i.test(linkedin);
const hasDomain = lead.isValidDomain && Boolean(lead.domain);

let verificationStatus = 'unverified';
const signals = [];

if (hasLinkedIn) {
  signals.push('verified_linkedin_presence');
}
if (hasDomain) {
  signals.push('registered_web_domain');
}
if (lead.isBusinessEmail) {
  signals.push('verified_business_email_mx');
}

if (hasDomain && (hasLinkedIn || lead.isBusinessEmail)) {
  verificationStatus = 'verified';
} else if (hasDomain || hasLinkedIn) {
  verificationStatus = 'provisional';
} else {
  verificationStatus = 'unverified';
}

const enrichedLead = {
  ...lead,
  verificationStatus,
  verificationSignals: signals,
  status: lead.isSuppressed ? 'suppressed' : (verificationStatus === 'verified' ? 'qualified' : 'new'),
  processedAt: new Date().toISOString()
};

return [{
  json: {
    eventId: item.eventId,
    status: 'processed',
    discovery: {
      lead: enrichedLead,
      action: lead.isSuppressed ? 'suppressed' : 'ingested'
    }
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: { discovery: item.json.discovery }
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
